// ── DFA Simulator ──────────────────────────────────────────────
// Accepts strings over {a,b} containing 'ab' as a substring.
// States: 0=start, 1=seen 'a', 2=seen 'ab' (accept)
const dfa = {
  start: 0,
  accept: new Set([2]),
  transitions: {
    0: { a: 1, b: 0 },
    1: { a: 1, b: 2 },
    2: { a: 2, b: 2 },
  },
};

function dfaRun(machine, input) {
  let state = machine.start;
  for (const ch of input) {
    const row = machine.transitions[state];
    if (!row || !(ch in row)) return false; // dead state
    state = row[ch];
  }
  return machine.accept.has(state);
}

console.log(dfaRun(dfa, 'bab'));   // true  — contains 'ab'
console.log(dfaRun(dfa, 'bbba')); // false — ends in 'a' only, no 'ab'
console.log(dfaRun(dfa, 'ab'));   // true
console.log(dfaRun(dfa, 'ba'));   // false

// ── NFA Simulator (subset construction at runtime) ──────────────
// NFA accepting strings ending in 'abb'
// States: {s0, s1, s2, s3}  s3 = accept
const nfa = {
  start: 's0',
  accept: new Set(['s3']),
  transitions: {
    s0: { a: ['s0', 's1'], b: ['s0'] },
    s1: { b: ['s2'] },
    s2: { b: ['s3'] },
    s3: {},
  },
};

function nfaRun(machine, input) {
  let current = new Set([machine.start]);
  for (const ch of input) {
    const next = new Set();
    for (const state of current) {
      const targets = machine.transitions[state]?.[ch] ?? [];
      targets.forEach(t => next.add(t));
    }
    current = next;
  }
  return [...current].some(s => machine.accept.has(s));
}

console.log(nfaRun(nfa, 'aabb'));  // true
console.log(nfaRun(nfa, 'abb'));   // true
console.log(nfaRun(nfa, 'ab'));    // false
console.log(nfaRun(nfa, 'abba')); // false

// ── Regex-to-NFA intuition (Thompson's construction fragments) ──
// Each operator builds a tiny NFA fragment:
//
//  Single symbol 'a':   (q0) --a--> ((q1))
//
//  Concatenation r·s:   NFA(r) → NFA(s)   (ε-link accept of r to start of s)
//
//  Union r|s:           new start --ε--> NFA(r)
//                                --ε--> NFA(s)  → new accept
//
//  Kleene star r*:      new start --ε--> NFA(r) --ε--> new accept
//                       NFA(r) accept --ε--> NFA(r) start   (loop)

// ── DFA minimisation: Myhill-Nerode equivalence classes ─────────
// Two strings x and y are Myhill-Nerode equivalent w.r.t. language L
// if for every suffix z:  xz ∈ L  iff  yz ∈ L
// The number of equivalence classes = the number of states in the minimal DFA.
// This is also why /ab/ needs 3 states: the classes are
//   [start], [seen 'a'], [seen 'ab' — accept]

// ── Key equivalence theorem ─────────────────────────────────────
// DFA ≡ NFA ≡ Regular Expression ≡ Regular Grammar
// All four formalisms define exactly the *regular languages*.
// Any one can be converted to any other (at most exponential blow-up DFA→NFA reversed).
console.log('DFA, NFA, regex, regular grammar are all equivalent in expressive power.');
